sys_rte_eb_script_operation.script:
/* global batch, output */

(function(batch, output) {
    const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Get HIRA Case reference - ';

    try {
        for (var i = 0; i < batch.length; i++) {
            //step1: access the input variables
            var posRepId = batch[i].input; //Value of the source field. 

            //step2: Your script/code goes here.
            var grHIRA = new GlideRecord('x_hccc_hoc_ohs_hira_case');

            grHIRA.get('position_reporting_position', posRepId);

            if (grHIRA.getRowCount() === 0) {
                gs.error(infoStr + 'ERROR: Unable to find matching case');
            } else {
                let sys_id = grHIRA.getUniqueValue();

                if (!sys_id) {
                    sys_id = grHIRA.getValue("sys_id")
                }
                if (!sys_id) {
                    gs.error(infoStr + 'ERROR: Unable to find matching case');
                }
                output[i] = sys_id;
                gs.debug(infoStr + 'posRepId: ' + posRepId + ' - HIRA Case Id: ' + sys_id);
            }
        }
    } catch (e) {
        gs.error(infoStr + 'ERROR: ' + e);
    }
})(batch, output);
